INSERT INTO public.source (id, title, source_type, author, edition, url, note)
SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/jiuwudaishi-114-may-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002710；EPUB电子本，纸本及异文待核", "id": "675ef925-399b-5635-8d28-840a732c02f8"}, {"title": "旧五代史·卷一百十四", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/jiuwudaishi-114-siege-labor-954/source.txt", "note": "《旧五代史》卷一百十四，段落 jiu-wudaishi-205deb4a7860-p002711；EPUB电子本，纸本及异文待核", "id": "8c039b5e-2944-563b-9e4e-22b7ac1e7143"}, {"title": "资治通鉴·后周纪三", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/tongjian-292-954-may-siege/source.txt", "note": "《资治通鉴》后周纪三，段落 zizhi-tongjian-a63549944a71-p003465；电子底本待考，分段待核", "id": "b06aa302-d0cb-5049-817e-af8209d7b81f"}, {"title": "新五代史·卷三十三", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/xinwudaishi-33-shi-yanchao-death/source.txt", "note": "《新五代史》卷三十三，段落 xin-wudaishi-b08f244b9241-p001204；EPUB电子本，纸本及异文待核", "id": "fc21e869-9c2e-5648-b0c3-ccc1888d5cb2"}, {"title": "新五代史·卷七十", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/2045d769bf64a5bf30604e638acd5ac322c1f6df/content/books/zizhi-tongjian/vol-292/year-0954/part-01/sources/library/xinwudaishi-70-sang-gui-zheng/source.txt", "note": "《新五代史》卷七十，段落 xin-wudaishi-b08f244b9241-p003453；EPUB电子本，纸本及异文待核", "id": "b9c6824e-61a1-5cb2-a3c0-57f770c04583"}, {"title": "新五代史·卷12·周本纪第十二·柴荣即位", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/3ba4c15f89bc0e4a416ae35be0615a8c443b7f49/content/books/zizhi-tongjian/vol-291/year-0954/part-01/sources/library/xinwudaishi-12-chairong-accession/source.txt", "note": "《新五代史》卷12·周本纪第十二·柴荣即位，段落 xin-wudaishi-b08f244b9241-p000376；已核上下文及传主，纸本及异文待核。", "id": "e8e8d8ba-d759-5bf8-896c-ca674bd3a93d"}, {"title": "宋史·卷253·折德扆传·父子身份", "source_type": "primary", "author": "脱脱等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/20d7e6560e7ea1d32a1da921d2ba225e55b0e6ce/content/books/zizhi-tongjian/vol-289/year-0950/part-03/sources/library/songshi-253-zhe-deyi-family/source.txt", "note": "《宋史》卷253·折德扆传·父子身份，段落 songshi-9c6e46fee832-p057379；已核上下文及传主，纸本及异文待核。", "id": "9f28e86e-3823-5060-9403-29712fbdff5a"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "王逵", "aliases": ["王进逵", "王進逵"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军指挥使。《新五代史》称王进逵，记为武陵人，早年是静江军士卒。951年与周行逢率修府士兵逃回朗州，参与当地军府事务。生卒年尚未录入。", "biography": null, "status": "draft", "id": "48ca3ee4-cced-5056-8a47-4394d3ad6237"}, {"name": "周行逢", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "楚国朗州静江军副使。951年与王逵率修府士兵逃回朗州。《宋史》记为朗州武陵人，早年因犯法被编入军队，凭骁勇升任军官。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1bc0f62b-e1c1-5468-a9db-2d2d5444ab22"}, {"name": "潘叔嗣", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "朗州人、刘言麾下牙将。952年任指挥使。史书称其果敢，与周行逢、张文表交好、共同成事。生卒年未载。", "biography": null, "status": "draft", "id": "0aa70d0f-a11c-50f9-a0e8-3e0a7278f26d"}, {"name": "柴荣", "aliases": ["郭荣", "柴榮", "郭榮"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本姓柴，950年《资治通鉴》以郭荣记名，任贵州刺史、天雄牙内都指挥使。父亲柴守礼是郭威妻子柴氏的兄长，郭威在尚无儿子时收养他。《新五代史》记他幼年跟随姑母在郭威家成长。《旧五代史》的任职纪年与通鉴不同，分别保留。", "biography": null, "status": "draft", "id": "697c1a4f-b373-5a78-8b47-330fe349a424"}, {"name": "杨衮", "aliases": ["楊袞"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "契丹将领。947年麻答派他率契丹及幽州兵援杜重威；他出兵后，恒州留守军减少，为当地起兵提供时机。生卒年未载。", "biography": null, "status": "draft", "id": "4115ee92-89ee-534e-a312-a3e1bd4793d6"}, {"name": "郑处谦", "aliases": ["鄭處謙"], "era": "五代十国", "birth_year": null, "death_year": 954, "description": "北汉代州防御使。954年五月拒绝契丹将杨衮召见，杀死守其城门的契丹骑兵后以城归降后周，被任为静塞军节度使。同月被代州将桑珪、解文遇杀死，两将诬称他暗通契丹。生年未载。", "biography": null, "status": "draft", "id": "f1630908-1006-5b10-8953-68159ad4cc8d"}, {"name": "耶律璟", "aliases": ["耶律述律", "述律王", "寿安王", "壽安王"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "耶律德光的长子，小字述律，封寿安王。《资治通鉴》949年条称述律王，记他派骑兵带走石重贵的宠姬赵氏、聂氏；《辽史》穆宗纪可核对姓名和亲支。949年时仍以述律王身份见于记载。", "biography": null, "status": "draft", "id": "81fb2030-5792-5006-be3c-0909be18feec"}, {"name": "安彦进", "aliases": ["安彥進"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "北汉石州刺史。954年四月后周王彦超、韩通攻克石州时被俘。生卒年未载。", "biography": null, "status": "draft", "id": "87995e29-8100-564c-8223-9214514aced7"}, {"name": "符彦卿", "aliases": ["符彥卿", "李彦卿", "李彥卿"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷275同光四年条所见人物：符彦卿，散员都指挥使、力战者。", "biography": null, "status": "draft", "id": "c837916f-0fdf-5954-a190-597b08cd9402"}, {"name": "郭从义", "aliases": ["郭從義"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "947年任郑州防御使。六月刘知远令他先入大梁清理宫禁，并秘密命令他杀李从益与王淑妃。生卒年尚未录入。", "biography": null, "status": "draft", "id": "1119f609-51af-51d0-9244-ca7ac5b42d47"}, {"name": "向训", "aliases": ["向訓"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周军官。951年与陈思让参与虒亭战事，《旧五代史》称监军，《宋史》称都监。生卒年及后续改名尚未据本次引文录入。", "biography": null, "status": "draft", "id": "1d29bcb9-6ec9-5369-89ff-ea67f0460acc"}, {"name": "白重赞", "aliases": ["白重贊"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后周武成节度使。953年九月己亥奏报已堵塞决口的黄河。生卒年未载。", "biography": null, "status": "draft", "id": "b6889cb5-a3c4-5b6a-aa6e-7feda1afc895"}, {"name": "史彦超（后周将领）", "aliases": ["史彦超", "史彥超"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "云州人，后周龙捷都指挥使。951年与王万敢、何徽防守晋州，抵抗北汉、契丹军。尚不与其他政权的同名将领合并，生卒年未录全。", "biography": null, "status": "draft", "id": "541b4701-1443-5a49-a822-4dc8d508ecee"}, {"name": "桑珪", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "代州将领。954年五月与解文遇杀死已降后周的郑处谦，诬称郑暗通契丹。《新五代史》也记桑珪杀郑处谦并以城降周。生卒年本段未载，后续行动另随编年录入。", "biography": null, "status": "draft", "id": "0d305981-af3a-59ad-ae51-cf8159ae3565"}, {"name": "解文遇", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "代州将领。954年五月与桑珪杀死郑处谦，诬告郑暗通契丹。生卒年未载。", "biography": null, "status": "draft", "id": "7c1cfe98-f5aa-56b2-a6d5-9751f752eca5"}, {"name": "李筠（原名李荣）", "aliases": ["李榮（控鶴指揮使）", "李荣（控鹤指挥使）"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "并州太原人，初名荣，后来因避周世宗讳改名筠。947年任控鹤指挥使，与何福进筹划恒州起兵，先夺甲库并组织官兵与居民作战。与李昪的父亲李荣、晚唐同名李筠分别建档。生卒年尚未录入。", "biography": null, "status": "draft", "id": "5fa92315-29cb-56c6-9108-8f703de9861a"}, {"name": "张永德", "aliases": ["張永德"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "阳曲人，郭威的女婿。950年任供奉官押班，奉命给昭义节度使常思送生日礼物；常思接到杀他的密诏后拘留观望，郭威取京师后释放并道歉。生卒年本批未录。", "biography": null, "status": "draft", "id": "c1584e5c-2a3c-5c28-bbe4-7c8a05161c51"}, {"name": "折德扆", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "折从远（后名折从阮）之子，任府州蕃汉马步都指挥使。950年五月己亥获任府州团练使，《宋史》也明确记其父为从阮。生卒年未载。", "biography": null, "status": "draft", "id": "11515d9f-5a90-5398-9366-6f44b89ca847"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
